import urllib.parse


class UrlPath:
    def __init__(self):
        self._segments = []
        self._with_end_tag = False

    @property
    def segments(self):
        return self._segments

    @segments.setter
    def segments(self, value):
        if not isinstance(value, (list, tuple)):
            raise TypeError("segments must be a list or tuple")
        self._segments = list(value)

    @property
    def with_end_tag(self):
        return self._with_end_tag

    @with_end_tag.setter
    def with_end_tag(self, value):
        if not isinstance(value, bool):
            raise TypeError("with_end_tag must be a boolean")
        self._with_end_tag = value

    def add(self, segment):
        fixed_segment = self.fix_path(segment)
        self.segments.append(fixed_segment)

    def parse(self, path, charset):
        if not path:
            return

        self.with_end_tag = path.endswith('/')
        fixed_path = self.fix_path(path)
        if not fixed_path:
            return

        split_parts = fixed_path.split('/')
        for seg in split_parts:
            decoded_seg = self._decode_segment(seg, charset)
            self.segments.append(decoded_seg)

    def _decode_segment(self, seg, charset):
        return urllib.parse.unquote(seg, encoding=charset)

    @staticmethod
    def fix_path(path):
        if not path:
            return ''

        segment_str = path.strip('/')
        return segment_str
